            try self.filters?.forEach {
                try $0.validate(name: "\(name).filters[]")
            }
            try self.validate(self.filters, name: "filters", parent: name, max: 30)
            try self.validate(self.filters, name: "filters", parent: name, min: 1)
            try self.validate(self.maxResults, name: "maxResults", parent: name, max: 100)
            try self.validate(self.maxResults, name: "maxResults", parent: name, min: 1)
            try self.validate(self.nextToken, name: "nextToken", parent: name, max: 8192)
            try self.validate(self.nextToken, name: "nextToken", parent: name, pattern: "^[a-zA-Z0-9+/=]+$")
            try self.validate(self.searchText, name: "searchText", parent: name, max: 512)
            try self.validate(self.searchText, name: "searchText", parent: name, min: 1)
            try self.validate(self.searchText, name: "searchText", parent: name, pattern: "[^\n]*")
        }

        private enum CodingKeys: String, CodingKey {
            case filters = "filters"
            case maxResults = "maxResults"
            case nextToken = "nextToken"
            case searchText = "searchText"
            case sortBy = "sortBy"
            case sortOrder = "sortOrder"
        }
    }

